def run(_context):
    import json
    tools = mb.list_library_tools(contains="TIW")
    # Filter for end mills and drills that might be useful
    print("=== END MILLS (flat) ===")
    for t in tools:
        if "Endmill" in t["description"] and t["corner_radius_mm"] == 0:
            print(json.dumps(t))
    print("\n=== DRILLS ===")
    for t in tools:
        if "Drill" in t["description"]:
            print(json.dumps(t))
    print("\n=== FACE MILL / FLY CUTTER ===")
    for t in tools:
        if "Fly" in t["description"] or "Face" in t["description"] or "face" in t["description"]:
            print(json.dumps(t))

