def run(_context):
    import json
    tools = mb.list_library_tools(contains="TIW")
    # Find all drills with full details
    print("=== ALL DRILLS ===")
    for t in tools:
        if "Drill" in t["description"]:
            print(f"  idx={t['index']}  D={t['diameter_mm']:.4f}mm  desc={t['description']}  flutes={t['flutes']}  flute_len={t['flute_length_mm']}")

    print("\n=== 1/4\" TOOLS (6.35mm) ===")
    for t in tools:
        if t["diameter_mm"] and abs(t["diameter_mm"] - 6.35) < 0.01:
            print(f"  idx={t['index']}  D={t['diameter_mm']:.4f}mm  cr={t['corner_radius_mm']}  desc={t['description']}  flutes={t['flutes']}")

    # Also look for tools close to 6.35mm diameter for drilling
    print("\n=== DRILLS NEAR 6.35mm ===")
    for t in tools:
        if "Drill" in t["description"] and t["diameter_mm"] and abs(t["diameter_mm"] - 6.35) < 1.0:
            print(f"  idx={t['index']}  D={t['diameter_mm']:.4f}mm  desc={t['description']}")

